        deal_identity_key as resolution_record_key
    from step_03_data_enrichment
),
curation_edges as (
    select
        resolution_record_key,
        1 as key_rank,
        'deal_external_id' as key_name,
        'deal_external_id:' || deal_external_id as key_value
    from curation_records
    where deal_external_id is not null
),
curation_labels_0 as (
    select distinct
        resolution_record_key,
        resolution_record_key as label
    from curation_edges
),
curation_values_1 as (
    select
        edges.key_value,
        min(labelled.label) as value_label
    from curation_edges as edges
    inner join curation_labels_0 as labelled
        on labelled.resolution_record_key = edges.resolution_record_key
    group by edges.key_value
),
curation_labels_1 as (
    select
        edges.resolution_record_key,
        min(matched.value_label) as label
    from curation_edges as edges
    inner join curation_values_1 as matched
        on matched.key_value = edges.key_value
    group by edges.resolution_record_key
),
curation_values_2 as (
    select
        edges.key_value,
        min(labelled.label) as value_label
    from curation_edges as edges
    inner join curation_labels_1 as labelled
        on labelled.resolution_record_key = edges.resolution_record_key
    group by edges.key_value
),
curation_labels_2 as (
    select
        edges.resolution_record_key,
        min(matched.value_label) as label
    from curation_edges as edges
    inner join curation_values_2 as matched
        on matched.key_value = edges.key_value
    group by edges.resolution_record_key
),
curation_components as (
    select
        resolution_record_key,
        label as component_id
    from curation_labels_2
),
curation_component_stats as (
    select
        component_id,
        count(*) as component_row_count
    from curation_components
    group by component_id
),
curation_component_keys as (
    select
        components.component_id,
        min(edges.key_rank) as best_key_rank
    from curation_components as components
    inner join curation_edges as edges
        on edges.resolution_record_key = components.resolution_record_key
    group by components.component_id
),
curation_resolved as (
    select
        records.deal_source_system,
        records.deal_identity_key,
        records.deal_normalised_name,
        records.deal_external_id,
        records.deal_business_key,
        records.deal_target_company_external_id,
        records.deal_converted_fund_external_id,
        records.deal_record_id,
        records.deal_name,
        records.deal_strategy,
        records.deal_originating_team,
        records.deal_channel,
        records.deal_sourced_on,
        records.deal_structure,
        records.deal_converted_record_type,
        records.deal_company_business_key,
        records.deal_fund_business_key,
        records.deal_external_identity,
        records.resolution_record_key,
        coalesce(components.component_id, records.resolution_record_key) as resolution_entity_key,
        coalesce(stats.component_row_count, 1) as resolution_row_count,
        case
            when keys.best_key_rank = 1 then 'deal_external_id'
        end as resolution_key_name,
        case
            when coalesce(stats.component_row_count, 1) > 1 then 'deterministic'
            else 'unresolved'
        end as resolution_tier,
        coalesce(stats.component_row_count, 1) = 1 as resolution_pending
    from curation_records as records
    left join curation_components as components
        on components.resolution_record_key = records.resolution_record_key
    left join curation_component_stats as stats
        on stats.component_id = components.component_id
    left join curation_component_keys as keys
        on keys.component_id = components.component_id
)

